<pre class="snippet-code-css lang-css prettyprint-override"><code>* {
  box-sizing: border-box
}

body {
  margin: 0;
  padding: 0;
  background: #4B89DA
}

.title {
  height: 160px;
  width: 100%;
  position: fixed;
  top: 0;
  padding: 2% 0 0 2%;
  background: #424953;
  z-index: 1
}

.title&gt;h1 {
  color: rgb(255, 255, 255);
  font-style: oblique;
  margin: 0
}

.title&gt;h1:first-child {
  font-size: 200%
}

.title&gt;h1:last-child {
  font-size: 500%
}

.main {
  width: 95%;
  position: relative;
  margin: calc(160px + 2%) 2.5% 2% 2.5%;
  background: white;
  padding: 2%
}</code></pre>
